sp_theme.css_variables:
/* == PTAG BOOT SPLASH ====================================================
   Lives in the THEME, not in a widget, and that placement is the whole point.
   The PTAG design system (fonts, tokens, base css, icon sprite) is injected at
   runtime by ptag_global's link function, so until Angular boots the document
   has no styling at all - that was the bare white page with the stock spinner.
   Widget css cannot fix it: it is delivered when the widget renders, i.e. after
   boot. Theme css IS compiled into sp-bootstrap-rem.scss and linked in <head>,
   so it paints on the first frame.

   Everything here is deliberately self-contained: literal colours and easings,
   no var(--pt-*), because the tokens do not exist yet at this point.

   The splash is cleared by ptag_global's link function adding .pt-booted to
   <html>. An animation can only be beaten by an animation, hence pt-boot-out
   rather than a plain opacity rule. There is also a hard 8s failsafe so a
   failed boot can never strand a full-screen overlay on the user. == */
html, body { background: #0a0e16; }

html::before {
  content: ""; position: fixed; inset: 0; z-index: 999999;
  background:
    radial-gradient(760px 420px at 50% 42%, rgba(99, 223, 78, 0.09), transparent 70%),
    radial-gradient(520px 320px at 78% 8%, rgba(56, 189, 248, 0.06), transparent 70%),
    #0a0e16;
  animation: pt-boot-breathe 2.6s cubic-bezier(0.22, 0.61, 0.24, 1) infinite,
             pt-boot-timeout 0s linear 8s forwards;
}
html::after {
  content: ""; position: fixed; z-index: 1000000;
  top: 50%; left: 50%; width: 42px; height: 42px; margin: -21px 0 0 -21px;
  border-radius: 50%;
  border: 2px solid rgba(99, 223, 78, 0.16);
  border-top-color: #63df4e;
  border-right-color: rgba(99, 223, 78, 0.55);
  animation: pt-boot-spin 1.05s linear infinite,
             pt-boot-timeout 0s linear 8s forwards;
}
html.pt-booted::before, html.pt-booted::after {
  animation: pt-boot-out 0.42s cubic-bezier(0.22, 0.61, 0.24, 1) forwards;
}
@keyframes pt-boot-spin { to { transform: rotate(360deg); } }
@keyframes pt-boot-breathe { 0%, 100% { opacity: 1; } 50% { opacity: 0.93; } }
@keyframes pt-boot-timeout { to { opacity: 0; visibility: hidden; } }
@keyframes pt-boot-out { to { opacity: 0; visibility: hidden; } }
@media (prefers-reduced-motion: reduce) {
  html::before { animation: pt-boot-timeout 0s linear 8s forwards; }
  html::after  { animation: pt-boot-timeout 0s linear 8s forwards; }
}
/* == PTAG BOOT SPLASH END == */
